#include <Arduino.h>

void setup() {
  pinMode(15, OUTPUT);
  digitalWrite(15, LOW);
  Serial1.setTX(0);
  Serial1.setRX(1);
  Serial1.begin(9600);
  Serial1.println("PICO_LOOP_BOOT");
}

void loop() {
  Serial1.write('A');
  delay(5);
  while (Serial1.available() > 0) {
    const int c = Serial1.read();
    if (c == 'A') {
      digitalWrite(15, !digitalRead(15));
      Serial1.println("PICO_LOOP_RX_OK");
    }
  }
  delay(40);
}

